DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='resolve_report'; definition:=replace(definition,'IF NOT public.is_admin_or_super(auth.uid()) THEN','IF NOT (public.is_admin_or_super(auth.uid()) OR public.has_ambassador_permission(auth.uid(),''denuncias:aprovar'')) THEN'); definition:=replace(definition,'IF _rep.id IS NULL THEN RAISE EXCEPTION ''Denúncia não encontrada''; END IF;', 'IF _rep.id IS NULL THEN RAISE EXCEPTION ''Denúncia não encontrada''; END IF; IF _action = ''unpublished'' AND NOT public.is_admin_or_super(auth.uid()) AND NOT public.has_ambassador_permission(auth.uid(), CASE WHEN _rep.entity_type=''job'' THEN ''vagas:publicar'' ELSE ''eventos:publicar'' END) THEN RAISE EXCEPTION ''Sem acesso para despublicar este conteúdo''; END IF;'); EXECUTE definition; END $$;
CREATE OR REPLACE FUNCTION public.guard_feed_moderation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_super(auth.uid()) AND OLD.kind<>'news' AND OLD.author_id<>auth.uid() THEN
 IF NOT public.has_ambassador_permission(auth.uid(),'feed:aprovar') OR (to_jsonb(NEW)-ARRAY['status','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at']) THEN RAISE EXCEPTION 'Moderação permite apenas ocultar ou restaurar o post'; END IF;
 END IF; RETURN NEW; END $$;
CREATE TRIGGER z_guard_feed_moderation BEFORE UPDATE ON public.member_feed_posts FOR EACH ROW EXECUTE FUNCTION public.guard_feed_moderation();
REVOKE ALL ON FUNCTION public.guard_feed_moderation() FROM PUBLIC,anon,authenticated;